function EventCard({ event }) {

    const handleDragStart = (e) => {

        e.dataTransfer.setData(
            "eventId",
            event.id
        );

    };

    return (

        <div
            className="event-card"
            draggable={true}
            onDragStart={handleDragStart}
        >

            <small>{event.time}</small>

            <h4>{event.title}</h4>

        </div>

    );

}

export default EventCard;
